{"content":"// Package cli parses the command line of the frob tool.
package cli

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// ErrUsage is wrapped by every parse error.
var ErrUsage = errors.New("usage error")

// Config is the parsed command line.
type Config struct {
	Verbose bool
	Count   int
	Output  string
	Tags    []string
	Args    []string
}

// Parse parses the argument slice into a Config.
func Parse(args []string) (Config, error) {
	cfg := Config{Count: 1, Output: "-"}

	i := 0
	sawDD := false
	for i < len(args) {
		arg := args[i]

		if sawDD {
			cfg.Args = append(cfg.Args, arg)
			i++
			continue
		}
		if arg == "--" {
			sawDD = true
			i++
			continue
		}
		if len(arg) >= 2 && arg[0] == '-' && arg[1] == '-' {
			if err := parseLong(&cfg, arg, args, &i); err != nil {
				return cfg, err
			}
			continue
		}
		if len(arg) >= 2 && arg[0] == '-' {
			if err := parseShort(&cfg, arg, args, &i); err != nil {
				return cfg, err
			}
			continue
		}
		// Bare "-" or a non-dash argument is positional.
		cfg.Args = append(cfg.Args, arg)
		i++
	}
	return cfg, nil
}

// value resolves the value for a flag: the remainder of the token
// (with a leading "=" stripped) or, when empty, the next argument.
func value(name, rest string, args []string, i *int) (string, error) {
	if strings.HasPrefix(rest, "=") {
		rest = rest[1:]
	}
	if rest != "" {
		return rest, nil
	}
	*i++
	if *i >= len(args) {
		return "", fmt.Errorf("%w: missing value for %s", ErrUsage, name)
	}
	return args[*i], nil
}

func parseLong(cfg *Config, arg, args string, i *int) error {
	body := arg[2:]
	name, val, hasVal := "", "", false
	if eq := strings.IndexByte(body, '='); eq >= 0 {
		name, val, hasVal = body[:eq], body[eq+1:], true
	} else {
		name = body
	}
	switch name {
	case "v", "verbose":
		if hasVal {
			return fmt.Errorf("%w: --verbose takes no argument", ErrUsage)
		}
		cfg.Verbose = true
	case "n", "count":
		v, err := value(arg, val, args, i)
		if err != nil {
			return err
		}
		n, err := strconv.Atoi(v)
		if err != nil {
			return fmt.Errorf("%w: invalid count %q for %s", ErrUsage, v, arg)
		}
		if n < 0 {
			return fmt.Errorf("%w: negative count %q for %s", ErrUsage, v, arg)
		}
		cfg.Count = n
	case "o", "output":
		v, err := value(arg, val, args, i)
		if err != nil {
			return err
		}
		cfg.Output = v
	case "tag":
		v, err := value(arg, val, args, i)
		if err != nil {
			return err
		}
		cfg.Tags = append(cfg.Tags, v)
	default:
		return fmt.Errorf("%w: unknown flag %s", ErrUsage, arg)
	}
	return nil
}

func parseShort(cfg *Config, arg, args string, i *int) error {
	chars := arg[1:]
	for len(chars) > 0 {
		c := string(chars[0])
		rest := chars[1:]
		switch c {
		case "v":
			cfg.Verbose = true
		case "n":
			v, err := value(c, rest, args, i)
			if err != nil {
				return err
			}
			n, err := strconv.Atoi(v)
			if err != nil {
				return fmt.Errorf("%w: invalid count %q for %s", ErrUsage, v, arg)
			}
			if n < 0 {
				return fmt.Errorf("%w: negative count %q for %s", ErrUsage, v, arg)
			}
			cfg.Count = n
			return nil // a value-taking flag ends the cluster
		case "o":
			v, err := value(c, rest, args, i)
			if err != nil {
				return err
			}
			cfg.Output = v
			return nil
		default:
			return fmt.Errorf("%w: unknown flag %s", ErrUsage, arg)
		}
		chars = rest
	}
	return nil
}
